package com.biocircular.notificaciones; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
record Notificacion(@NotBlank String destinatario,@NotBlank String asunto,@NotBlank String mensaje,String tipo){} record Enviada(UUID id,OffsetDateTime fecha,Notificacion contenido){}
@RestController @RequestMapping("/api/notificaciones") public class NotificacionesController{final List<Enviada> historial=new ArrayList<>();@PostMapping({"/enviar","/recoleccion","/lote","/incidente"})ResponseEntity<Enviada> enviar(@RequestBody @jakarta.validation.Valid Notificacion n){Enviada e=new Enviada(UUID.randomUUID(),OffsetDateTime.now(),n);historial.add(e);return ResponseEntity.status(201).body(e);}@GetMapping List<Enviada> listar(){return List.copyOf(historial);}}
